//! CLDR locale display names (languages, scripts, regions, variants).
//!
//! The table is generated by tools/unicode/format/generate_display_names.py
//! and falls back from the display locale to English, then to the raw code.

const std = @import("std");

const blob = @embedFile("display_names_data.bin");

const header_len = 24;
const locale_count = readU16(8);
const entry_count = readU32(12);
const string_length = readU32(16);

const locale_offset = header_len;
const entry_offset = locale_offset + locale_count * 42;
const strings_offset = entry_offset + entry_count * 8;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJLD") or
        blob[4] != 1)
    {
        @compileError("invalid display name data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid display name data lengths");
    }
}

pub const Kind = enum { language, script, region, variant };

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn strAt(offset: u32) []const u8 {
    if (offset == 0) return "";
    return std.mem.sliceTo(blob[strings_offset + @as(usize, offset) ..], 0);
}

const LocaleRecord = struct {
    id: []const u8,
    starts: [4]u32,
    counts: [4]u16,
    pattern: []const u8,
    separator: []const u8,
    key_type: []const u8,
};

fn localeAt(index: usize) LocaleRecord {
    const base = locale_offset + index * 42;
    const id_offset = readU32(base);
    const id_length = blob[base + 4];
    return .{
        .id = blob[strings_offset + @as(usize, id_offset) ..][0..id_length],
        .starts = .{
            readU32(base + 6),
            readU32(base + 12),
            readU32(base + 18),
            readU32(base + 24),
        },
        .counts = .{
            readU16(base + 10),
            readU16(base + 16),
            readU16(base + 22),
            readU16(base + 28),
        },
        .pattern = strAt(readU32(base + 30)),
        .separator = strAt(readU32(base + 34)),
        .key_type = strAt(readU32(base + 38)),
    };
}

fn lookupLocale(locale_name: []const u8) ?LocaleRecord {
    var low: usize = 0;
    var high: usize = locale_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const record = localeAt(middle);
        switch (std.mem.order(u8, record.id, locale_name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return record,
        }
    }
    return null;
}

fn findLocale(locale_name: []const u8) ?LocaleRecord {
    if (lookupLocale(locale_name)) |record| return record;
    if (std.mem.indexOfAny(u8, locale_name, "-_")) |position| {
        if (lookupLocale(locale_name[0..position])) |record| return record;
    }
    return lookupLocale("en");
}

fn lookupName(record: LocaleRecord, kind: Kind, code: []const u8) ?[]const u8 {
    const index: usize = @intFromEnum(kind);
    var low: usize = record.starts[index];
    var high: usize = record.starts[index] + record.counts[index];
    while (low < high) {
        const middle = low + (high - low) / 2;
        const base = entry_offset + middle * 8;
        const entry_code = strAt(readU32(base));
        switch (std.mem.order(u8, entry_code, code)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return strAt(readU32(base + 4)),
        }
    }
    return null;
}

const RootEntry = struct {
    kind: Kind,
    code: []const u8,
    name: []const u8,
};

const root_entries = [_]RootEntry{
    .{ .kind = .variant, .code = "POSIX", .name = "Computer" },
};

fn lookupRootName(kind: Kind, code: []const u8) ?[]const u8 {
    for (root_entries) |entry| {
        if (entry.kind == kind and std.mem.eql(u8, entry.code, code)) {
            return entry.name;
        }
    }
    return null;
}

/// Localized display name for a language, script, region, or variant code.
pub fn name(locale_name: []const u8, kind: Kind, code: []const u8) []const u8 {
    if (findLocale(locale_name)) |record| {
        if (lookupName(record, kind, code)) |value| return value;
    }
    // ICU falls back to its root bundle, which only carries a few legacy
    // names; otherwise the code itself is returned.
    if (lookupRootName(kind, code)) |value| return value;
    return code;
}

fn applyPair(
    allocator: std.mem.Allocator,
    pattern: []const u8,
    first: []const u8,
    second: []const u8,
) ![]u8 {
    var output = std.ArrayList(u8).empty;
    errdefer output.deinit(allocator);
    var index: usize = 0;
    while (index < pattern.len) {
        if (pattern[index] == '{' and index + 2 < pattern.len and
            pattern[index + 2] == '}')
        {
            if (pattern[index + 1] == '0') {
                try output.appendSlice(allocator, first);
            } else if (pattern[index + 1] == '1') {
                try output.appendSlice(allocator, second);
            }
            index += 3;
            continue;
        }
        try output.append(allocator, pattern[index]);
        index += 1;
    }
    return output.toOwnedSlice(allocator);
}

fn normalize(code: []const u8, buffer: []u8, upper: bool) []const u8 {
    const length = @min(code.len, buffer.len);
    for (code[0..length], 0..) |character, index| {
        buffer[index] = if (upper)
            std.ascii.toUpper(character)
        else
            std.ascii.toLower(character);
    }
    return buffer[0..length];
}

/// Display name for a locale identifier such as `fr-CA` or `zh-Hant-TW`.
pub fn localeDisplayNameAlloc(
    allocator: std.mem.Allocator,
    display_locale: []const u8,
    target: []const u8,
) ![]u8 {
    const record = findLocale(display_locale) orelse
        lookupLocale("en") orelse return allocator.dupe(u8, target);
    var language_buffer: [16]u8 = undefined;
    var script_buffer: [16]u8 = undefined;
    var region_buffer: [16]u8 = undefined;
    var language: []const u8 = "";
    var script: []const u8 = "";
    var region: []const u8 = "";
    var variants: [4][]const u8 = undefined;
    var variant_buffers: [4][16]u8 = undefined;
    var variant_count: usize = 0;

    var iterator = std.mem.tokenizeAny(u8, target, "-_");
    var first = true;
    while (iterator.next()) |subtag| {
        if (first) {
            first = false;
            language = normalize(subtag, &language_buffer, false);
            continue;
        }
        if (script.len == 0 and subtag.len == 4 and
            std.ascii.isAlphabetic(subtag[0]))
        {
            script = normalize(subtag, &script_buffer, false);
            script_buffer[0] = std.ascii.toUpper(script_buffer[0]);
            continue;
        }
        if (region.len == 0 and
            ((subtag.len == 2 and std.ascii.isAlphabetic(subtag[0])) or
                (subtag.len == 3 and std.ascii.isDigit(subtag[0]))))
        {
            region = normalize(subtag, &region_buffer, true);
            continue;
        }
        if (variant_count < variants.len and subtag.len <= 8) {
            variants[variant_count] = normalize(
                subtag,
                &variant_buffers[variant_count],
                true,
            );
            variant_count += 1;
        }
    }
    if (language.len == 0) {
        return allocator.dupe(u8, target);
    }

    const language_name = if (std.mem.eql(u8, language, "und"))
        @as([]const u8, "root")
    else
        name(display_locale, .language, language);

    var detail: ?[]u8 = null;
    defer if (detail) |value| allocator.free(value);
    if (script.len != 0) {
        detail = try allocator.dupe(u8, name(display_locale, .script, script));
    }
    if (region.len != 0) {
        const region_name = name(display_locale, .region, region);
        if (detail) |current| {
            const combined = try applyPair(
                allocator,
                record.separator,
                current,
                region_name,
            );
            allocator.free(current);
            detail = combined;
        } else {
            detail = try allocator.dupe(u8, region_name);
        }
    }
    for (variants[0..variant_count]) |variant| {
        const variant_name = name(display_locale, .variant, variant);
        if (detail) |current| {
            const combined = try applyPair(
                allocator,
                record.separator,
                current,
                variant_name,
            );
            allocator.free(current);
            detail = combined;
        } else {
            detail = try allocator.dupe(u8, variant_name);
        }
    }
    if (detail) |value| {
        return applyPair(allocator, record.pattern, language_name, value);
    }
    return allocator.dupe(u8, language_name);
}

test "display names" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    try testing.expectEqualStrings("French", name("en", .language, "fr"));
    try testing.expectEqualStrings("United States", name("en", .region, "US"));
    try testing.expectEqualStrings("Traditional", name("en", .script, "Hant"));
    try testing.expectEqualStrings("Computer", name("en", .variant, "POSIX"));
    try testing.expectEqualStrings("français", name("fr", .language, "fr"));
    try testing.expectEqualStrings("qqq", name("en", .language, "qqq"));

    const cases = [_]struct { display: []const u8, target: []const u8, expected: []const u8 }{
        .{ .display = "en", .target = "fr_CA", .expected = "French (Canada)" },
        .{ .display = "en", .target = "en_US", .expected = "English (United States)" },
        .{ .display = "en", .target = "zh_Hant_TW", .expected = "Chinese (Traditional, Taiwan)" },
        .{ .display = "en", .target = "sr_Latn_RS", .expected = "Serbian (Latin, Serbia)" },
        .{ .display = "en", .target = "und_US", .expected = "root (United States)" },
        .{ .display = "en", .target = "en_US_POSIX", .expected = "English (United States, Computer)" },
        .{ .display = "zh", .target = "en_US", .expected = "英语（美国）" },
    };
    for (cases) |case| {
        const value = try localeDisplayNameAlloc(
            allocator,
            case.display,
            case.target,
        );
        defer allocator.free(value);
        try testing.expectEqualStrings(case.expected, value);
    }
}

test "display name conformance" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const fixture = @embedFile("display_names_conformance.bin");
    try testing.expect(fixture.len >= 12);
    try testing.expectEqualStrings("CJLE", fixture[0..4]);
    const case_count = std.mem.readInt(u32, fixture[8..12], .little);
    var cursor: usize = 12;
    var failures: usize = 0;
    var total: usize = 0;
    var printed: usize = 0;
    for (0..case_count) |_| {
        const kind = fixture[cursor];
        const display_length = fixture[cursor + 1];
        const code_length = fixture[cursor + 2];
        const expected_length = std.mem.readInt(u16, fixture[cursor + 4 ..][0..2], .little);
        cursor += 16;
        const display_locale = fixture[cursor .. cursor + display_length];
        cursor += display_length;
        const code = fixture[cursor .. cursor + code_length];
        cursor += code_length;
        const expected = fixture[cursor .. cursor + expected_length];
        cursor += expected_length;
        total += 1;
        if (kind < 4) {
            const actual = name(display_locale, @enumFromInt(kind), code);
            if (!std.mem.eql(u8, actual, expected)) {
                failures += 1;
                if (printed < 30) {
                    printed += 1;
                    std.debug.print(
                        "display mismatch {s} kind {d} code {s}: got '{s}' expected '{s}'\n",
                        .{ display_locale, kind, code, actual, expected },
                    );
                }
            }
            continue;
        }
        const actual = localeDisplayNameAlloc(
            allocator,
            display_locale,
            code,
        ) catch |err| {
            failures += 1;
            if (printed < 30) {
                printed += 1;
                std.debug.print(
                    "display mismatch {s} locale {s}: {s}\n",
                    .{ display_locale, code, @errorName(err) },
                );
            }
            continue;
        };
        defer allocator.free(actual);
        if (!std.mem.eql(u8, actual, expected)) {
            failures += 1;
            if (printed < 30) {
                printed += 1;
                std.debug.print(
                    "display mismatch {s} locale {s}: got '{s}' expected '{s}'\n",
                    .{ display_locale, code, actual, expected },
                );
            }
        }
    }
    std.debug.print("display name conformance: {d}/{d} passed\n", .{ total - failures, total });
    try testing.expect(failures == 0);
}
